package com.mycompany.rentalmanagement.servlet;import com.mycompany.rentalmanagement.dao.*;import com.mycompany.rentalmanagement.DBConnection;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;import java.util.*;
@WebServlet("/reports") public class ReportServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{List<Map<String,Object>> rows=new ArrayList<>();String sql="SELECT r.id,c.full_name customer,v.registration_number,r.start_date,r.expected_return_date,r.actual_return_date,r.status,COALESCE(r.final_total,r.estimated_total) total,COALESCE(SUM(p.amount),0) paid FROM rentals r JOIN customers c ON c.id=r.customer_id JOIN vehicles v ON v.id=r.vehicle_id LEFT JOIN payments p ON p.rental_id=r.id GROUP BY r.id,c.full_name,v.registration_number,r.start_date,r.expected_return_date,r.actual_return_date,r.status,r.final_total,r.estimated_total ORDER BY r.id DESC";try(Connection c=DBConnection.getConnection();Statement st=c.createStatement();ResultSet rs=st.executeQuery(sql)){while(rs.next()){Map<String,Object> m=new LinkedHashMap<>();for(String k:new String[]{"id","customer","vehicle","start","expected","actual","status","total","paid"})m.put(k,rs.getObject(switch(k){case "customer"->"full_name";case "vehicle"->"registration_number";case "start"->"start_date";case "expected"->"expected_return_date";case "actual"->"actual_return_date";case "total"->"total";case "paid"->"paid";default->k;}));rows.add(m);}}r.setAttribute("rows",rows);r.setAttribute("stats",new DashboardDAO().stats());r.getRequestDispatcher("/WEB-INF/views/reports.jsp").forward(r,s);}catch(Exception e){r.setAttribute("error",e.getMessage());r.getRequestDispatcher("/WEB-INF/views/error.jsp").forward(r,s);}}}
